def _children(stage):
    return sorted(name for name, deps in DEPENDENCIES.items() if stage in deps)


def descendants(stage):
    out, queue = [], [stage]
    while queue:
        parent = queue.pop(0)
        for child in _children(parent):
            if child not in out:
                out.append(child); queue.append(child)
    return out


# Generated by GitHub Copilot - Oct-05-2026
def build_run_manifest(metadata, stage_status, issues, quality=None):
    """Distinguish direct failures, degraded descendants and unaffected valid modules."""
    states = {k: dict(v) for k, v in stage_status.items()}
    quality = quality or {}
    hard_failures = [k for k, v in states.items() if v.get('status') == 'failed']
    unavailable = [k for k, v in states.items() if v.get('status') == 'unavailable']
    blocked = [k for k, v in states.items() if v.get('status') == 'blocked']
    direct = sorted(set(hard_failures + unavailable + [key for key, state in states.items() if state.get('status') == 'cancelled']))
    partial_roots = [name for name, state in states.items() if state.get('status') in ('partial', 'degraded')]
    functional_degradations = []
    if quality.get('micro_track_ratio') is not None and quality['micro_track_ratio'] >= .5:
        functional_degradations.append({'stage': '07_people_tracking', 'cause': 'severe_microtrack_fragmentation_proxy',
                                       'metric': 'micro_track_ratio', 'value': quality['micro_track_ratio'],
                                       'impact': 'persistent_identity_and_camera_targets'})
    if quality.get('active_speaker_coverage') == 0:
        functional_degradations.append({'stage': '10_active_speaker', 'cause': 'speaker_person_evidence_unresolved',
                                       'metric': 'active_speaker_coverage', 'value': 0,
                                       'impact': 'intelligent_camera_focus_unavailable'})
    causal_roots = sorted(set(direct + partial_roots + [row['stage'] for row in functional_degradations if row['stage'] in states]))
    root = direct[0] if direct else causal_roots[0] if causal_roots else None
    causes = {child: [] for stage in causal_roots for child in descendants(stage) if child in states}
    for stage in causal_roots:
        for child in descendants(stage):
            if child in causes:
                causes[child].append(stage)
    affected = sorted(causes)
    degraded = []
    source_preserving = []
    for name, state in states.items():
        if name in causes and name not in direct and state.get('status') not in ('skipped', 'blocked'):
            state['effective_status'] = 'source_preservation_fallback' if name in ('12_camera_timeline', '18b_global_camera_planner', '19_camera_director') else 'degraded_by_missing_capability'
            state['dependency_reasons'] = [{'stage': stage, 'status': states[stage].get('status')} for stage in causes[name]]
            degraded.append(name)
            if state['effective_status'] == 'source_preservation_fallback':
                source_preserving.append(name)
        else:
            state['effective_status'] = state.get('status')
        if name in ('12_camera_timeline', '18b_global_camera_planner', '19_camera_director') and quality.get('source_preservation_fraction', 0) >= .999:
            state['effective_status'] = 'source_preservation_fallback'
            if name not in source_preserving:
                source_preserving.append(name)
        cause_rows = [{'stage': parent, 'status': states[parent].get('status')} for parent in causes.get(name, [])]
        functional = [row for row in functional_degradations if row['stage'] == name]
        status_map = {'ok': 'VALID', 'partial': 'PARTIAL', 'degraded': 'DEGRADED', 'failed': 'FAILED',
                      'unavailable': 'FAILED', 'skipped': 'SKIPPED', 'blocked': 'BLOCKED', 'cancelled': 'BLOCKED'}
        state.update(status_model='DEGRADED' if name in degraded or functional or name in source_preserving else status_map.get(state.get('status'), 'PARTIAL'),
                     cause=functional or [issue for issue in issues if issue.get('stage') == name] or cause_rows,
                     severity='high' if functional or name in source_preserving else 'high' if name in direct else 'medium' if name in partial_roots or name in degraded else None,
                     impact=[row['impact'] for row in functional] or ['upstream_evidence_degraded'] if cause_rows else [row['impact'] for row in functional],
                     upstream_cause=cause_rows, downstream_effects=descendants(name) if name in causal_roots else [],
                     fallback_used=name in source_preserving,
                     recommended_action='Preserve source framing until speaker/person and crop evidence resolve.' if name in source_preserving else
                        'Review the named evidence gaps; replay only affected downstream stages.' if name in causal_roots or name in degraded else None)
    valid = [name for name, state in states.items() if state.get('status') == 'ok' and name not in causes]
    first_reprocess = root or (blocked[0] if blocked else None)
    return {
        'schema_version': '1.0',
        'run_id': (metadata.get('sha256') or digest(metadata))[:16],
        'analyzer_version': metadata.get('analyzer_version'),
        'analysis_status': 'partial' if any(v.get('status') in ('partial','unavailable','failed','blocked','cancelled') for v in states.values()) else 'complete',
        'root_cause_stage': root,
        'root_cause_status': states.get(root, {}).get('status') if root else None,
        'descendants_affected': affected,
        'modules_still_valid': valid,
        'direct_failures': direct,
        'degradation_roots': causal_roots,
        'functional_degradations': functional_degradations,
        'degraded_descendants': degraded,
        'partially_valid_modules': [name for name, state in states.items() if state.get('status') == 'partial'],
        'unaffected_modules': [name for name in states if name not in causes and name not in direct],
        'source_preserving_fallback_modules': source_preserving,
        'dependency_reasons': causes,
        'unavailable_capabilities': unavailable,
        'blocked_stages': blocked,
        'recommended_action': (f'Reprocessar a partir de {first_reprocess} após corrigir a causa raiz.' if first_reprocess else 'Nenhuma falha causal registrada.'),
        'first_stage_to_reprocess': first_reprocess,
        'stage_status': states,
        'issues': issues,
    }
